"""Module holding the implementation for providing BIP log specific log file from airphone.
"""
import os


class AirphoneBipLogFileProvider:
    """Class to get the trace file for bip logs. Only the format of pcap is supported for bip trace files.
    """

    def get_bip_log_file(self, log_directory, collector_config):
        pcap_files = [filename for filename in os.listdir(log_directory)
                      if filename.lower().endswith(".pcap")]

        pcap_files = [os.path.join(log_directory, filename) for filename in pcap_files]
        return pcap_files
